import React, { useState } from "react";
import axios from "axios";

export default function AddDriverForm() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    licenseNumber: "",
    status: "active",
    isAvailable: true,
    currentOrders: 0,
    lat: "",
    lng: ""
  });

  const [message, setMessage] = useState("");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await axios.post("http://localhost:5000/api/drivers", {
        ...form,
        location: {
          lat: parseFloat(form.lat),
          lng: parseFloat(form.lng),
        },
      });
      setMessage("✅ Driver added successfully!");
      setForm({
        name: "",
        email: "",
        phone: "",
        licenseNumber: "",
        status: "active",
        isAvailable: true,
        currentOrders: 0,
        lat: "",
        lng: ""
      });
    } catch (error) {
      console.error(error);
      setMessage("❌ Failed to add driver");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ padding: "20px", maxWidth: "400px", margin: "auto" }}>
      <h2>Add Driver</h2>
      {["name", "email", "phone", "licenseNumber", "lat", "lng"].map((field) => (
        <input
          key={field}
          name={field}
          placeholder={field}
          value={(form as any)[field]}
          onChange={handleChange}
          style={{ marginBottom: "10px", width: "100%", padding: "8px" }}
          required
        />
      ))}
      <button type="submit" style={{ padding: "10px 20px" }}>Add Driver</button>
      {message && <p style={{ color: message.includes("✅") ? "green" : "red" }}>{message}</p>}
    </form>
  );
}
